"use client";

import { Slice } from "@tiptap/pm/model";
import { EditorState } from "@tiptap/pm/state";
import { EditorContent, useEditor } from "@tiptap/react";
import { type ComponentProps, type CSSProperties, useEffect, useMemo, useRef, useState } from "react";
import type { MarkdownEditorKnobStyle } from "@/components/control-ui/knob-contracts/markdown-editor-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { Textarea } from "@/components/control-ui/ui/textarea";
import { MarkdownEditorContext, useMarkdownEditor } from "./markdown-editor/context";
import { MarkdownEditorDragHandle } from "./markdown-editor/drag-handle";
import { createMarkdownCodec, hasMarkdownContent, markdownExtensions, requiresMarkdownSource } from "./markdown-editor/extensions";
import type { MarkdownImageUploader } from "./markdown-editor/uploads";
import { useImageUploads } from "./markdown-editor/use-image-uploads";

export type MarkdownEditorStatus = { isEmpty: boolean; hasPendingUploads: boolean };
export type MarkdownEditorProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "style"> & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (markdown: string) => void;
  disabled?: boolean;
  onUploadImage?: MarkdownImageUploader;
  maxImageBytes?: number;
  onStatusChange?: (status: MarkdownEditorStatus) => void;
  style?: CSSProperties & MarkdownEditorKnobStyle;
};

export function MarkdownEditor({
  value,
  defaultValue = "",
  onValueChange,
  disabled = false,
  onUploadImage,
  maxImageBytes = 10 * 1024 * 1024,
  onStatusChange,
  children,
  className,
  ...props
}: MarkdownEditorProps) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const markdown = value ?? internalValue;
  const [sourceMode, setSourceMode] = useState(false);
  const [contentAttributes, setContentAttributes] = useState<Record<string, string>>({ role: "textbox", "aria-multiline": "true" });
  const [codec] = useState(createMarkdownCodec);
  const sourceRequired = useMemo(() => requiresMarkdownSource(markdown, codec), [markdown, codec]);
  const source = sourceMode || sourceRequired;
  const lastValue = useRef(markdown);
  const [extensions] = useState(markdownExtensions);
  const handlers = useRef<{ upload: (files: File[], position?: number) => void; cancelAll: () => void } | null>(null);

  function setMarkdown(next: string) {
    lastValue.current = next;
    setInternalValue(next);
    onValueChange?.(next);
  }

  const editor = useEditor({
    extensions,
    immediatelyRender: false,
    shouldRerenderOnTransaction: false,
    content: sourceRequired ? "" : markdown,
    contentType: "markdown",
    editable: !disabled,
    onUpdate: ({ editor: currentEditor }) => setMarkdown(currentEditor.getMarkdown()),
    editorProps: {
      attributes: contentAttributes,
      handlePaste: (view, event) => {
        if (disabled) return false;
        const files = Array.from(event.clipboardData?.files ?? []);
        if (onUploadImage && files.length > 0) {
          event.preventDefault();
          handlers.current?.upload(files);
          return true;
        }
        const text = event.clipboardData?.getData("text/plain");
        if (!text || event.clipboardData?.getData("text/html") || requiresMarkdownSource(text, codec)) return false;
        const document = view.state.schema.nodeFromJSON(codec.parse(text));
        event.preventDefault();
        view.dispatch(view.state.tr.replaceSelection(Slice.maxOpen(document.content)).scrollIntoView());
        return true;
      },
      handleDrop: (view, event, _slice, moved) => {
        const files = Array.from(event.dataTransfer?.files ?? []);
        if (moved || !onUploadImage || disabled || files.length === 0) return false;
        event.preventDefault();
        const position = view.posAtCoords({ left: event.clientX, top: event.clientY })?.pos;
        handlers.current?.upload(files, position);
        return true;
      },
    },
  });
  const imageUploads = useImageUploads(editor, onUploadImage, maxImageBytes);
  useEffect(() => {
    handlers.current = imageUploads;
  });

  useEffect(() => {
    if (!editor) return;
    editor.setEditable(!disabled, false);
  }, [editor, disabled]);

  useEffect(() => {
    if (!editor) return;
    const externalReset = lastValue.current !== markdown;
    if (externalReset) handlers.current?.cancelAll();
    if (source) {
      lastValue.current = markdown;
      return;
    }
    if (editor.getMarkdown() !== markdown) {
      editor.commands.setContent(markdown, { contentType: "markdown", emitUpdate: false });
      if (externalReset) {
        editor.view.updateState(EditorState.create({ schema: editor.schema, doc: editor.state.doc, plugins: editor.state.plugins }));
        editor.view.dispatch(editor.state.tr);
      }
    }
    lastValue.current = markdown;
  }, [editor, markdown, source]);

  const isEmpty = source ? markdown.trim() === "" : !hasMarkdownContent(codec.parse(markdown));
  const hasPendingUploads = imageUploads.uploads.length > 0;
  useEffect(() => {
    onStatusChange?.({ isEmpty, hasPendingUploads });
  }, [onStatusChange, isEmpty, hasPendingUploads]);

  return (
    <MarkdownEditorContext
      value={{
        editor,
        disabled,
        source,
        markdown,
        sourceRequired,
        setSource: setSourceMode,
        setMarkdown,
        setContentAttributes,
        canUpload: Boolean(onUploadImage),
        ...imageUploads,
      }}
    >
      <div
        data-control-ui="markdown-editor"
        data-control-family="markdown-editor"
        data-slot="root"
        data-disabled={disabled ? "" : undefined}
        className={cn("min-w-0", className)}
        {...props}
      >
        {children}
      </div>
    </MarkdownEditorContext>
  );
}

export type MarkdownEditorContentProps = {
  label: string;
  placeholder?: string;
  autoFocus?: boolean;
  className?: string;
};

export function MarkdownEditorContent({ label, placeholder, autoFocus = false, className }: MarkdownEditorContentProps) {
  const container = useRef<HTMLDivElement>(null);
  const { editor, disabled, source, sourceRequired, markdown, setMarkdown, setContentAttributes } = useMarkdownEditor();
  useEffect(() => {
    setContentAttributes({
      role: "textbox",
      "aria-multiline": "true",
      "aria-label": label,
      "aria-disabled": String(disabled),
      "data-placeholder": placeholder ?? "",
    });
  }, [setContentAttributes, label, disabled, placeholder]);

  useEffect(() => {
    if (editor && autoFocus && !source && !disabled) editor.commands.focus("end");
  }, [editor, autoFocus, source, disabled]);

  if (source || !editor)
    return (
      <div data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="source" className={className}>
        {sourceRequired ? (
          <p role="status">This content uses Markdown that is only available in source mode. Its source is preserved.</p>
        ) : null}
        <Textarea
          aria-label={label}
          placeholder={placeholder}
          value={markdown}
          disabled={disabled || !editor}
          onChange={(event) => setMarkdown(event.target.value)}
          rows={5}
          autoFocus={autoFocus}
          style={{
            "--cui-field-background": "transparent",
            "--cui-field-border-width": "0px",
            "--cui-field-radius": "0px",
            "--cui-field-shadow": "none",
          }}
        />
      </div>
    );
  return (
    <div ref={container} data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="content" className={className}>
      <EditorContent editor={editor} />
      <MarkdownEditorDragHandle container={container} />
    </div>
  );
}

import type { Editor } from "@tiptap/core";
import { createContext, useContext } from "react";
import type { MarkdownImageUpload } from "./uploads";

export type MarkdownEditorContextValue = {
  editor: Editor | null;
  disabled: boolean;
  source: boolean;
  markdown: string;
  sourceRequired: boolean;
  setSource: (source: boolean) => void;
  setMarkdown: (value: string) => void;
  setContentAttributes: (attributes: Record<string, string>) => void;
  canUpload: boolean;
  uploads: MarkdownImageUpload[];
  upload: (files: File[], position?: number) => void;
  retryUpload: (id: string) => void;
  removeUpload: (id: string) => void;
  uploadError: string | null;
};

export const MarkdownEditorContext = createContext<MarkdownEditorContextValue | null>(null);

export function useMarkdownEditor() {
  const context = useContext(MarkdownEditorContext);
  if (!context) throw new Error("Markdown editor parts require a MarkdownEditor parent.");
  return context;
}

"use client";

import { closeHistory } from "@tiptap/pm/history";
import { NodeSelection } from "@tiptap/pm/state";
import { GripVerticalIcon } from "lucide-react";
import { type RefObject, useEffect, useRef, useState } from "react";
import { Button } from "@/components/control-ui/ui/button";
import { LiveStatus } from "@/components/control-ui/ui/live-status";
import { useMarkdownEditor } from "./context";

type BlockHandle = { position: number; top: number };

export function MarkdownEditorDragHandle({ container }: { container: RefObject<HTMLDivElement | null> }) {
  const { editor, disabled, source } = useMarkdownEditor();
  const [block, setBlock] = useState<BlockHandle | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const button = useRef<HTMLButtonElement>(null);
  const dragging = useRef(false);

  useEffect(() => {
    const surface = container.current;
    if (!editor || !surface || disabled || source) return;
    function show(blockPosition: number) {
      if (!editor || !surface) return;
      const node = editor.view.nodeDOM(blockPosition);
      if (!(node instanceof HTMLElement)) return;
      const top = node.getBoundingClientRect().top - surface.getBoundingClientRect().top + surface.scrollTop;
      setBlock((current) => (current?.position === blockPosition && current.top === top ? current : { position: blockPosition, top }));
    }
    function track(event: MouseEvent) {
      if (!editor || dragging.current || button.current?.contains(event.target instanceof Node ? event.target : null)) return;
      const rect = editor.view.dom.getBoundingClientRect();
      const padding = Number.parseFloat(getComputedStyle(editor.view.dom).paddingInlineStart);
      const hit = editor.view.posAtCoords({ left: Math.max(event.clientX, rect.left + padding), top: event.clientY });
      if (!hit) return;
      const resolved = editor.state.doc.resolve(hit.pos);
      show(resolved.depth > 0 ? resolved.before(1) : hit.pos);
    }
    function selectionChanged() {
      if (!editor || dragging.current) return;
      const { $from } = editor.state.selection;
      show($from.depth > 0 ? $from.before(1) : $from.pos);
    }
    function hide() {
      if (!dragging.current && document.activeElement !== button.current) setBlock(null);
    }
    surface.addEventListener("mousemove", track);
    surface.addEventListener("mouseleave", hide);
    editor.on("transaction", selectionChanged).on("focus", selectionChanged);
    return () => {
      surface.removeEventListener("mousemove", track);
      surface.removeEventListener("mouseleave", hide);
      editor.off("transaction", selectionChanged).off("focus", selectionChanged);
      editor.view.dragging = null;
    };
  }, [editor, container, disabled, source]);

  if (!editor || disabled || source) return null;
  const selected = editor.state.selection.$from;
  const position = block?.position ?? (selected.depth > 0 ? selected.before(1) : selected.pos);

  function move(direction: -1 | 1) {
    if (!editor) return;
    const { doc, tr } = editor.state;
    const node = doc.nodeAt(position);
    if (!node) return;
    const adjacent = direction === -1 ? doc.resolve(position).nodeBefore : doc.nodeAt(position + node.nodeSize);
    if (!adjacent) return;
    const target = direction === -1 ? position - adjacent.nodeSize : position + adjacent.nodeSize;
    tr.delete(position, position + node.nodeSize).insert(target, node);
    tr.setSelection(NodeSelection.create(tr.doc, target));
    editor.view.dispatch(closeHistory(tr).scrollIntoView());
    setAnnouncement(`Block moved ${direction === -1 ? "up" : "down"}.`);
  }

  return (
    <>
      <Button
        ref={button}
        type="button"
        variant="ghost"
        size="xs"
        iconOnly
        data-markdown-drag-handle=""
        data-visible={block ? "" : undefined}
        aria-label="Drag to reorder block"
        aria-description="Drag this block, or use Alt+ArrowUp and Alt+ArrowDown to move it."
        title="Drag to reorder · Alt+↑/↓ to move"
        draggable
        style={{ top: block?.top }}
        onClick={() => editor.commands.setNodeSelection(position)}
        onKeyDown={(event) => {
          if (!event.altKey || !["ArrowUp", "ArrowDown"].includes(event.key)) return;
          event.preventDefault();
          move(event.key === "ArrowUp" ? -1 : 1);
        }}
        onDragStart={(event) => {
          const { view } = editor;
          const selection = NodeSelection.create(view.state.doc, position);
          const node = view.nodeDOM(position);
          view.dispatch(view.state.tr.setSelection(selection));
          const { dom, text, slice } = view.serializeForClipboard(selection.content());
          event.dataTransfer.clearData();
          event.dataTransfer.setData("text/html", dom.innerHTML);
          event.dataTransfer.setData("text/plain", text);
          event.dataTransfer.effectAllowed = "copyMove";
          if (node instanceof HTMLElement) event.dataTransfer.setDragImage(node, 0, 0);
          view.dragging = { slice, move: true };
          dragging.current = true;
        }}
        onDragEnd={() => {
          editor.view.dragging = null;
          dragging.current = false;
          setBlock(null);
        }}
      >
        <GripVerticalIcon aria-hidden="true" />
      </Button>
      <LiveStatus message={announcement} />
    </>
  );
}

import { type JSONContent, Node } from "@tiptap/core";
import Image from "@tiptap/extension-image";
import { TaskItem, TaskList } from "@tiptap/extension-list";
import Paragraph from "@tiptap/extension-paragraph";
import { TableKit } from "@tiptap/extension-table";
import { Markdown, MarkdownManager } from "@tiptap/markdown";
import StarterKit from "@tiptap/starter-kit";

export function isEditorUrl(value: string, image = false): boolean {
  if (!value || /[\s\\]/.test(value) || Array.from(value).some((character) => character.charCodeAt(0) < 32)) return false;
  if (value.startsWith("/") && !value.startsWith("//")) return true;
  if (!image && value.startsWith("#")) return true;
  try {
    const url = new URL(value);
    return ["https:", "http:", ...(image ? [] : ["mailto:"])].includes(url.protocol);
  } catch {
    return false;
  }
}

const SafeImage = Image.extend({
  renderMarkdown: (node) => {
    const src = String(node.attrs?.src ?? "").replace(/[()]/g, (character) => `\\${character}`);
    const alt = String(node.attrs?.alt ?? "").replace(/[\\[\]]/g, (character) => `\\${character}`);
    const title = String(node.attrs?.title ?? "").replace(/[\\"]/g, (character) => `\\${character}`);
    return title ? `![${alt}](${src} "${title}")` : `![${alt}](${src})`;
  },
  addAttributes() {
    return {
      ...this.parent?.(),
      src: {
        default: null,
        parseHTML: (element) => {
          const src = element.getAttribute("src") ?? "";
          return isEditorUrl(src, true) ? src : null;
        },
        renderHTML: (attributes) => ({ src: isEditorUrl(attributes.src ?? "", true) ? attributes.src : undefined }),
      },
    };
  },
});

const MarkdownParagraph = Paragraph.extend({
  parseMarkdown: (token, helpers) => {
    const content = helpers.parseInline(token.tokens ?? []);
    const first = content[0];
    const empty = content.length === 1 && first?.type === "text" && ["&nbsp;", "\u00a0"].includes(first.text ?? "");
    return helpers.createNode("paragraph", undefined, empty ? [] : content);
  },
});

export const ImageUpload = Node.create({
  name: "imageUpload",
  group: "block",
  atom: true,
  selectable: true,
  addAttributes: () => ({ id: { default: null }, name: { default: "Image" } }),
  renderHTML: ({ node }) => ["div", { "data-image-upload": "", role: "status" }, `Image: ${node.attrs.name}`],
  renderMarkdown: () => "",
});

export function markdownExtensions() {
  return [
    StarterKit.configure({
      underline: false,
      paragraph: false,
      link: { openOnClick: false, isAllowedUri: (url) => isEditorUrl(url) },
    }),
    MarkdownParagraph,
    SafeImage.configure({ allowBase64: false, inline: true }),
    TaskList,
    TaskItem.configure({ nested: true, HTMLAttributes: { "data-type": "taskItem" } }),
    TableKit.configure({ table: { resizable: false } }),
    ImageUpload,
    Markdown,
  ];
}

export function createMarkdownCodec() {
  return new MarkdownManager({ extensions: markdownExtensions() });
}

const supportedTokens = new Set([
  "space",
  "code",
  "heading",
  "hr",
  "blockquote",
  "list",
  "list_item",
  "paragraph",
  "text",
  "escape",
  "link",
  "image",
  "strong",
  "em",
  "codespan",
  "br",
  "del",
  "table",
  "def",
  "taskList",
  "taskItem",
]);

function unsupportedToken(value: unknown): boolean {
  if (Array.isArray(value)) return value.some(unsupportedToken);
  if (typeof value !== "object" || value === null) return false;
  if ("type" in value && typeof value.type === "string") {
    if (!supportedTokens.has(value.type)) return true;
    if (
      (value.type === "image" || value.type === "link") &&
      "href" in value &&
      typeof value.href === "string" &&
      !isEditorUrl(value.href, value.type === "image")
    )
      return true;
  }
  return Object.values(value).some(unsupportedToken);
}

export function requiresMarkdownSource(markdown: string, codec: MarkdownManager): boolean {
  return unsupportedToken(codec.instance.lexer(markdown));
}

export function hasMarkdownContent(document: JSONContent): boolean {
  if (document.type === "image") return true;
  if (document.type === "text" && document.text?.trim()) return true;
  return document.content?.some(hasMarkdownContent) ?? false;
}

"use client";

import type { ChainedCommands, Editor } from "@tiptap/core";
import {
  Heading1Icon,
  Heading2Icon,
  Heading3Icon,
  ListChecksIcon,
  ListIcon,
  ListOrderedIcon,
  MinusIcon,
  QuoteIcon,
  SquareCodeIcon,
  TextIcon,
  UserIcon,
} from "lucide-react";
import { useEffect, useEffectEvent, useRef } from "react";
import { isComposingKey, type TriggerMenuItemData, useTriggerMenu } from "@/components/control-ui/hooks/use-trigger-menu";
import { detectTrigger } from "@/components/control-ui/lib/trigger-detect";
import { LiveStatus } from "@/components/control-ui/ui/live-status";
import { TriggerMenu, TriggerMenuEmpty, TriggerMenuIcon, TriggerMenuItem, TriggerMenuList } from "@/components/control-ui/ui/trigger-menu";
import { useMarkdownEditor } from "./context";
import { isEditorUrl } from "./extensions";

export type MarkdownEditorMention = TriggerMenuItemData & { href: string };
type EditorSuggestion = TriggerMenuItemData & { href?: string; command?: (chain: ChainedCommands) => ChainedCommands };

const blockCommands: readonly EditorSuggestion[] = [
  { id: "paragraph", label: "Text", keywords: ["paragraph"], icon: <TextIcon />, command: (chain) => chain.clearNodes().setParagraph() },
  {
    id: "heading-1",
    label: "Heading 1",
    keywords: ["h1", "title"],
    icon: <Heading1Icon />,
    command: (chain) => chain.clearNodes().setHeading({ level: 1 }),
  },
  {
    id: "heading-2",
    label: "Heading 2",
    keywords: ["h2", "subtitle"],
    icon: <Heading2Icon />,
    command: (chain) => chain.clearNodes().setHeading({ level: 2 }),
  },
  {
    id: "heading-3",
    label: "Heading 3",
    keywords: ["h3"],
    icon: <Heading3Icon />,
    command: (chain) => chain.clearNodes().setHeading({ level: 3 }),
  },
  { id: "bullet-list", label: "Bullet list", icon: <ListIcon />, command: (chain) => chain.clearNodes().toggleBulletList() },
  {
    id: "ordered-list",
    label: "Numbered list",
    keywords: ["ordered"],
    icon: <ListOrderedIcon />,
    command: (chain) => chain.clearNodes().toggleOrderedList(),
  },
  {
    id: "task-list",
    label: "Task list",
    keywords: ["todo", "checklist"],
    icon: <ListChecksIcon />,
    command: (chain) => chain.clearNodes().toggleTaskList(),
  },
  { id: "quote", label: "Quote", keywords: ["blockquote"], icon: <QuoteIcon />, command: (chain) => chain.clearNodes().toggleBlockquote() },
  { id: "code-block", label: "Code block", icon: <SquareCodeIcon />, command: (chain) => chain.clearNodes().setCodeBlock() },
  { id: "divider", label: "Divider", keywords: ["rule", "separator"], icon: <MinusIcon />, command: (chain) => chain.setHorizontalRule() },
];

function readTrigger(editor: Editor) {
  const { selection } = editor.state;
  const { $from } = selection;
  if (
    !editor.isFocused ||
    !selection.empty ||
    !$from.parent.isTextblock ||
    $from.parent.type.spec.code ||
    editor.isActive("code") ||
    editor.isActive("link")
  )
    return null;
  const text = $from.parent.textBetween(0, $from.parentOffset, undefined, "\ufffc");
  const match = detectTrigger(text, ["/", "@"]);
  if (!match || (match.char === "/" && match.start !== 0)) return null;
  return { ...match, start: $from.start() + match.start, end: $from.pos };
}

export type MarkdownEditorSuggestionsProps = {
  /** The application supplies people and their persistent profile URLs. */
  mentions?: readonly MarkdownEditorMention[] | ((query: string) => readonly MarkdownEditorMention[]);
  onMentionSelect?: (mention: MarkdownEditorMention) => void;
};

export function MarkdownEditorSuggestions({ mentions = [], onMentionSelect }: MarkdownEditorSuggestionsProps) {
  const activeItem = useRef<HTMLDivElement>(null);
  const { editor, disabled, source } = useMarkdownEditor();
  const enabled = Boolean(editor) && !disabled && !source;
  const controller = useTriggerMenu<EditorSuggestion>({
    triggers: [
      { char: "/", items: blockCommands },
      { char: "@", items: mentions },
    ],
    onCommit: (item) => {
      if (!editor || !enabled || item.disabled) return;
      const match = readTrigger(editor);
      if (!match) return;
      const range = { from: match.start, to: match.end };
      if (match.char === "/" && item.command) item.command(editor.chain().focus().deleteRange(range)).run();
      if (match.char === "@" && item.href && isEditorUrl(item.href)) {
        editor
          .chain()
          .focus()
          .insertContentAt(range, [
            { type: "text", text: `@${item.label}`, marks: [{ type: "link", attrs: { href: item.href } }] },
            { type: "text", text: " " },
          ])
          .run();
        onMentionSelect?.({ ...item, href: item.href });
      }
    },
  });
  const report = useEffectEvent(() => {
    if (!editor) return;
    const match = enabled ? readTrigger(editor) : null;
    const coords = match ? editor.view.coordsAtPos(match.end) : null;
    controller.report(match, coords ? new DOMRect(coords.left, coords.top, 1, coords.bottom - coords.top) : null);
  });
  const handleKeyDown = useEffectEvent((event: KeyboardEvent) => {
    if (!editor || !enabled || isComposingKey(event) || event.metaKey || event.ctrlKey || event.altKey || !readTrigger(editor)) return;
    if (controller.handleKeyDown(event.key)) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  });
  useEffect(() => {
    if (!editor || !enabled) return;
    const dom = editor.view.dom;
    editor.on("transaction", report).on("focus", report).on("blur", report);
    dom.addEventListener("keydown", handleKeyDown, true);
    return () => {
      editor.off("transaction", report).off("focus", report).off("blur", report);
      dom.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [editor, enabled]);

  const open = enabled && controller.open;
  useEffect(() => {
    if (!editor || !open) return;
    const owner = editor.view.dom.ownerDocument;
    owner.addEventListener("scroll", report, { capture: true, passive: true });
    owner.defaultView?.addEventListener("resize", report);
    return () => {
      owner.removeEventListener("scroll", report, true);
      owner.defaultView?.removeEventListener("resize", report);
    };
  }, [editor, open]);
  const { activeIndex, activeChar, query } = controller;
  // biome-ignore lint/correctness/useExhaustiveDependencies: changing the active result or query must reveal the current option.
  useEffect(() => {
    if (open) activeItem.current?.scrollIntoView({ block: "nearest" });
  }, [open, activeIndex, activeChar, query]);
  const { "aria-controls": controls, "aria-activedescendant": activeDescendant } = controller.inputAria;
  useEffect(() => {
    if (!editor || !enabled) return;
    const dom = editor.view.dom;
    const attributes = {
      "aria-autocomplete": "list",
      "aria-haspopup": "listbox",
      "aria-controls": controls,
      "aria-activedescendant": activeDescendant,
    };
    for (const [name, value] of Object.entries(attributes)) {
      if (value) dom.setAttribute(name, value);
      else dom.removeAttribute(name);
    }
    return () => {
      for (const name of Object.keys(attributes)) dom.removeAttribute(name);
    };
  }, [editor, enabled, controls, activeDescendant]);

  const label = controller.activeChar === "@" ? "Mention people" : "Insert block";
  const emptyLabel = controller.activeChar === "@" ? "No people found" : "No commands found";
  return (
    <>
      <LiveStatus message={open ? `${controller.items.length} ${label.toLowerCase()} suggestions` : ""} />
      <TriggerMenu open={open} onOpenChange={controller.setOpen} anchorRect={controller.anchorRect} side="bottom">
        {controller.items.length === 0 ? <TriggerMenuEmpty>{emptyLabel}</TriggerMenuEmpty> : null}
        <TriggerMenuList id={controller.listId} aria-label={label}>
          {controller.items.map((item, index) => (
            <TriggerMenuItem
              key={item.id}
              id={controller.optionId(index)}
              active={index === controller.activeIndex}
              disabled={item.disabled || (item.href !== undefined && !isEditorUrl(item.href))}
              ref={index === controller.activeIndex ? activeItem : undefined}
              onPointerMove={() => controller.setActiveIndex(index)}
              onClick={() => controller.select(item)}
            >
              <TriggerMenuIcon>{item.icon ?? <UserIcon />}</TriggerMenuIcon>
              <span className="min-w-0 flex-1 truncate">{item.label}</span>
              {item.description ? <span className="truncate text-muted-foreground">{item.description}</span> : null}
            </TriggerMenuItem>
          ))}
        </TriggerMenuList>
      </TriggerMenu>
    </>
  );
}

